contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint withdrawProbe) public payable {
        require(withdrawProbe >= 0);

        uint beforeBal = address(c).balance;

        // withdrawAll with no credit must not revert and must not change C's balance
        bool reverted0;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted0 = true; } else { reverted0 = false; }
        assert(!reverted0 && address(c).balance == beforeBal);
    }

    receive() external payable {}
}

