pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 withdrawProbe) internal {
        vm.assume(withdrawProbe >= 0);
        uint beforeBal = address(c).balance;
        bool reverted0;
        try c.withdrawAll() { reverted0 = false; } catch { reverted0 = true; }
        assertTrue(!reverted0 && address(c).balance == beforeBal);
    }

    function testFuzz_run(uint256 withdrawProbe) public {
        _run(withdrawProbe);
    }

    receive() external payable {}
}
